const result = $input.first().json;
if (result.status !== 'succeeded' || !Array.isArray(result.items)) throw new Error('YouTube comments did not return preview items.');
const comments = result.items.map((comment) => ({ id: comment.comment_id, author: comment.author?.display_name, content: comment.content, likes: comment.like_count, published: comment.published_time }));
return [{ json: { source: 'YouTube public comments', source_count: comments.length, request_ids: [result.request_id], prompt: JSON.stringify({ video_id: $('Configure Inputs').first().json.video_id, comments }) } }];

const answer = $input.first().json.choices?.[0]?.message?.content;
if (!answer) throw new Error('The text model returned no message content.');
const evidence = $('Prepare Evidence').first().json;
return [{ json: { summary: answer, source: evidence.source, source_count: evidence.source_count, request_ids: evidence.request_ids } }];
